const body = $input.first().json.body || $input.first().json;
const msg = body.message || body;
const eventType = msg.type || msg.event || '';

const esInicio = eventType === 'assistant-request';
const esFin = eventType.includes('end') || eventType.includes('End');

const call = msg.call || {};
const transcript = msg.artifact?.transcript || msg.transcript || '';
const callerPhone = call.customer?.number || call.phoneNumber || 'unknown';
const duration = Math.round((call.endedAt && call.startedAt
  ? (new Date(call.endedAt) - new Date(call.startedAt)) / 1000
  : msg.durationSeconds || 0));
const endedReason = call.endedReason || msg.endedReason || 'unknown';

return [{ json: {
  esInicio,
  esFin,
  skip: !esInicio && !esFin,
  eventType,
  transcript,
  callerPhone,
  duration,
  endedReason,
  fechaLlamada: new Date().toISOString().split('T')[0]
}}];

const docContent = $input.first().json.body?.content || [];

let textoDoc = '';
if (Array.isArray(docContent)) {
  for (const elemento of docContent) {
    const parrafo = elemento.paragraph;
    if (parrafo?.elements) {
      for (const el of parrafo.elements) {
        if (el.textRun?.content) {
          textoDoc += el.textRun.content;
        }
      }
    }
  }
} else if (typeof docContent === 'string') {
  textoDoc = docContent;
}

textoDoc = textoDoc.trim();

const promptContexto = `Eres Marco, asesor de atención al cliente de Crating Express Miami. Fabricamos cajones y embalajes de madera a medida con certificación ISPM-15.

IDIOMA: Comienza SIEMPRE en español. Si el cliente responde en inglés, cambia al inglés y mantén ese idioma hasta el final, incluyendo la despedida.

TU ROL EN ESTA LLAMADA:
- Dar información general sobre servicios, precios aproximados, tiempos, ISPM-15, etc.
- Responder preguntas del cliente con precisión y de forma directa.
- Si el cliente quiere una cotización → decirle EXACTAMENTE esto: "Gracias, para una cotización gratis y en pocos segundos por favor envíanos los detalles por mensaje de texto a este mismo número. ¿Necesitas alguna otra información?"
- Si el cliente habla inglés y quiere cotización → "Thanks, for a free quote in seconds please text us the details to this number. Anything else I can help with?"

LO QUE NO HACES:
- NO recopiles medidas, peso, dimensiones ni ningún dato para cotización en esta llamada.
- NO preguntes el modelo del artículo ni cuántas unidades necesita para cotizar.
- NO proceses cotizaciones por teléfono — el proceso es por mensaje de texto.

TONO: Directo, cálido, ambiente de embarques acelerado de Miami. Sin frases de relleno. Solo las palabras necesarias.

SOBRE CRATING EXPRESS:
${textoDoc}

Recuerda: si no sabes algo con certeza, ofrece conectar al cliente por WhatsApp al +1 786-788-0417 o email cratingexpress01@gmail.com.`;

return [{ json: { promptContexto } }];

const data = $input.first().json;

const transcript = data.transcript || '';
const noTranscript = !transcript || transcript.length < 20;

const prompt = `Extract lead information from this phone call transcript. Return ONLY valid JSON with these fields:
- nombre: caller's name if mentioned, else ""
- empresa: company name if mentioned, else ""
- interes: one of "cotizacion", "informacion", "urgente", "no_interesado", "otro"
- notas: 1-2 sentence summary of what the caller needed in Spanish

Transcript:
${transcript.slice(0, 2000)}

Return only JSON, no explanation.`;

return [{ json: { ...data, prompt, noTranscript } }];

const ctx = $('🔧 Preparar Prompt Extracción').item.json;

const clasifMap = { cotizacion: 'caliente', urgente: 'caliente', informacion: 'tibio', no_interesado: 'frio', otro: 'frio', sin_transcript: 'frio' };
function calcPhone(raw) {
  const s = raw && raw !== 'unknown' ? String(raw) : '';
  return s ? (s.startsWith('+') ? s : '+' + s) : ('vapi_' + Date.now());
}

if (ctx.noTranscript) {
  return [{ json: { ...ctx, nombre: '', empresa: '', interes: 'sin_transcript', notas: '', phoneFormatted: calcPhone(ctx.callerPhone), clasificacionVoice: clasifMap['sin_transcript'] } }];
}

let extracted = { nombre: '', empresa: '', interes: 'otro', notas: '' };
try {
  const raw = $input.item.json;
  const text = raw.choices?.[0]?.message?.content || '{}';
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) extracted = JSON.parse(jsonMatch[0]);
} catch (e) {}

return [{ json: { ...ctx, ...extracted, phoneFormatted: calcPhone(ctx.callerPhone), clasificacionVoice: clasifMap[extracted.interes] || 'frio' } }];

