const board = $json;
const telefono = $('🔍 Parsear Extracción').item.json.phoneFormatted;
let found = null;
for (const etapa of Object.keys(board)) {
  const deals = board[etapa];
  if (!Array.isArray(deals)) continue;
  for (const deal of deals) {
    if (deal.telefono === telefono) { found = deal; break; }
  }
  if (found) break;
}
return [{ json: { dealExiste: !!found, dealId: found ? found.id : null, telefono } }];

